parameters.jsCode:
const msgRaw = $('Dados').item.json.conversation || '';
const msg = msgRaw.trim();
const msgNorm = msg.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

let state = null;
try { state = JSON.parse($('Buscar Estado Admin').item.json.adminStateRaw || 'null'); } catch (e) { state = null; }

let config = null;
try { config = JSON.parse($('Buscar Config Admin').item.json.configRaw || 'null'); } catch (e) { config = null; }
if (!config || !config.servicos) {
  config = { servicos: [], horario: { dias: "Segunda a sábado", abertura: "09:00", fechamento: "19:00" } };
}

function formatMenu() {
  return "Você entrou no modo de edição do agente.\n\nDigite 1 para alterar nome do serviço, valores ou horário de funcionamento\nDigite 2 para incluir novo serviço\nDigite 3 para excluir um serviço\n\n(Digite \"sair\" a qualquer momento pra encerrar)";
}

function formatConfirmacao(resumo) {
  return `Confira se está certo:\n\n${resumo}\n\nDigite 1 para confirmar\nDigite 2 para corrigir\nDigite 3 para voltar ao menu anterior`;
}

function parseValor(str) {
  let s = (str || '').replace(/[^0-9,.]/g, '');
  if (s.includes(',') && s.includes('.')) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }
  return parseFloat(s);
}

function parseDuracao(str) {
  const s = (str || '').toLowerCase().trim();
  const numMatch = s.match(/(\d+(?:[.,]\d+)?)/);
  if (!numMatch) return NaN;
  const num = parseFloat(numMatch[1].replace(',', '.'));
  if (/h(ora)?s?\b/.test(s) && !/min/.test(s)) {
    return Math.round(num * 60);
  }
  return Math.round(num);
}

let reply = "";
let newState = null;
let newConfig = null;
let exit = false;

if (["sair", "cancelar", "pronto", "encerrar"].includes(msgNorm)) {
  reply = "Saiu do modo de edição.";
  exit = true;
} else if (!state || !state.step) {
  reply = formatMenu();
  newState = { step: "menu" };
} else if (state.step === "menu") {
  if (msg === "1") {
    reply = "O que deseja alterar?\nDigite \"servico\" para editar nome, valor ou duração de um serviço existente\nDigite \"horario\" para alterar o horário de funcionamento";
    newState = { step: "aguardando_escolha_1" };
  } else if (msg === "2") {
    reply = "Envie no formato:\nNome - Valor - Duração\nEx: massagem relaxante - R$10,00 - 45 minutos";
    newState = { step: "aguardando_incluir" };
  } else if (msg === "3") {
    const lista = config.servicos.map(s => "- " + s.nome).join('\n');
    reply = "Envie o nome exato do serviço que deseja excluir:\n" + lista;
    newState = { step: "aguardando_excluir" };
  } else {
    reply = "Opção inválida.\n\n" + formatMenu();
    newState = { step: "menu" };
  }
} else if (state.step === "aguardando_escolha_1") {
  if (msgNorm === "servico") {
    const lista = config.servicos.map(s => `- ${s.nome} (R$${s.valor}, ${s.duracao}min)`).join('\n');
    reply = "Envie no formato:\nNome atual - Novo nome - Novo valor - Nova duração\n(repita o nome se não quiser mudar)\nEx: Botox - Botox - R$850,00 - 30 minutos\n\nServiços atuais:\n" + lista;
    newState = { step: "aguardando_editar_servico" };
  } else if (msgNorm === "horario") {
    reply = `Envie no formato:\nDias - Abertura - Fechamento\nEx: Segunda a sábado - 09:00 - 18:00\n\nAtual: ${config.horario.dias} - ${config.horario.abertura} - ${config.horario.fechamento}`;
    newState = { step: "aguardando_horario" };
  } else {
    reply = "Não entendi. Digite \"servico\" ou \"horario\".";
    newState = state;
  }

// ---- ETAPA 1: coletar dados ----
} else if (state.step === "aguardando_editar_servico") {
  const parts = msg.split('-').map(p => p.trim());
  if (parts.length !== 4) {
    reply = "Formato inválido. Envie no formato:\nNome atual - Novo nome - Novo valor - Nova duração\nEx: Botox - Botox - R$850,00 - 30 minutos";
    newState = state;
  } else {
    const [nomeAtual, novoNome, novoValorStr, novaDuracaoStr] = parts;
    const idx = config.servicos.findIndex(s => s.nome.toLowerCase() === nomeAtual.toLowerCase());
    if (idx === -1) {
      reply = `Não encontrei o serviço "${nomeAtual}". Tente novamente ou digite "sair".`;
      newState = state;
    } else {
      const novoValor = parseValor(novoValorStr);
      const novaDuracao = parseDuracao(novaDuracaoStr);
      if (isNaN(novoValor) || isNaN(novaDuracao)) {
        reply = "Não consegui entender o valor ou a duração. Envie no formato:\nNome atual - Novo nome - Novo valor - Nova duração\nEx: Botox - Botox - R$850,00 - 30 minutos";
        newState = state;
      } else {
        const pendente = { idx, nome: novoNome, valor: novoValor, duracao: novaDuracao };
        const resumo = `Serviço: ${nomeAtual} → ${novoNome}\nValor: R$${novoValor.toFixed(2).replace('.', ',')}\nDuração: ${novaDuracao} minutos`;
        reply = formatConfirmacao(resumo);
        newState = { step: "confirmando_editar_servico", pendente };
      }
    }
  }
} else if (state.step === "aguardando_horario") {
  const parts = msg.split('-').map(p => p.trim());
  if (parts.length !== 3) {
    reply = "Formato inválido. Envie: Dias - Abertura - Fechamento";
    newState = state;
  } else {
    const [dias, abertura, fechamento] = parts;
    const pendente = { dias, abertura, fechamento };
    const resumo = `Dias: ${dias}\nAbertura: ${abertura}\nFechamento: ${fechamento}`;
    reply = formatConfirmacao(resumo);
    newState = { step: "confirmando_horario", pendente };
  }
} else if (state.step === "aguardando_incluir") {
  const parts = msg.split('-').map(p => p.trim());
  if (parts.length !== 3) {
    reply = "Formato inválido. Envie no formato:\nNome - Valor - Duração\nEx: massagem relaxante - R$10,00 - 45 minutos";
    newState = state;
  } else {
    const [nome, valorStr, duracaoStr] = parts;
    const valor = parseValor(valorStr);
    const duracao = parseDuracao(duracaoStr);
    if (isNaN(valor) || isNaN(duracao)) {
      reply = "Não consegui entender o valor ou a duração. Envie no formato:\nNome - Valor - Duração\nEx: massagem relaxante - R$10,00 - 45 minutos";
      newState = state;
    } else {
      const pendente = { nome, valor, duracao };
      const resumo = `Novo serviço: ${nome}\nValor: R$${valor.toFixed(2).replace('.', ',')}\nDuração: ${duracao} minutos`;
      reply = formatConfirmacao(resumo);
      newState = { step: "confirmando_incluir", pendente };
    }
  }
} else if (state.step === "aguardando_excluir") {
  const idx = config.servicos.findIndex(s => s.nome.toLowerCase() === msg.toLowerCase());
  if (idx === -1) {
    reply = `Não encontrei o serviço "${msg}". Tente novamente ou digite "sair".`;
    newState = state;
  } else {
    const pendente = { idx, nome: config.servicos[idx].nome };
    const resumo = `Excluir o serviço: ${config.servicos[idx].nome}`;
    reply = formatConfirmacao(resumo);
    newState = { step: "confirmando_excluir", pendente };
  }

// ---- ETAPA 2: confirmar e aplicar ----
} else if (state.step === "confirmando_editar_servico") {
  if (msg === "1") {
    const p = state.pendente;
    config.servicos[p.idx] = { nome: p.nome, valor: p.valor, duracao: p.duracao };
    newConfig = config;
    reply = `Atualizado! "${p.nome}" agora custa R$${p.valor} e dura ${p.duracao} minutos.\n\n` + formatMenu();
    newState = { step: "menu" };
  } else if (msg === "2") {
    reply = "Envie novamente no formato:\nNome atual - Novo nome - Novo valor - Nova duração\nEx: Botox - Botox - R$850,00 - 30 minutos";
    newState = { step: "aguardando_editar_servico" };
  } else if (msg === "3") {
    reply = formatMenu();
    newState = { step: "menu" };
  } else {
    reply = "Digite 1 para confirmar, 2 para corrigir, ou 3 para voltar ao menu.";
    newState = state;
  }
} else if (state.step === "confirmando_horario") {
  if (msg === "1") {
    config.horario = state.pendente;
    newConfig = config;
    reply = `Horário atualizado: ${config.horario.dias}, ${config.horario.abertura} às ${config.horario.fechamento}.\n\n` + formatMenu();
    newState = { step: "menu" };
  } else if (msg === "2") {
    reply = "Envie novamente no formato: Dias - Abertura - Fechamento";
    newState = { step: "aguardando_horario" };
  } else if (msg === "3") {
    reply = formatMenu();
    newState = { step: "menu" };
  } else {
    reply = "Digite 1 para confirmar, 2 para corrigir, ou 3 para voltar ao menu.";
    newState = state;
  }
} else if (state.step === "confirmando_incluir") {
  if (msg === "1") {
    const p = state.pendente;
    config.servicos.push({ nome: p.nome, valor: p.valor, duracao: p.duracao });
    newConfig = config;
    reply = `Serviço "${p.nome}" incluído: R$${p.valor}, ${p.duracao} minutos.\n\n` + formatMenu();
    newState = { step: "menu" };
  } else if (msg === "2") {
    reply = "Envie novamente no formato:\nNome - Valor - Duração\nEx: massagem relaxante - R$10,00 - 45 minutos";
    newState = { step: "aguardando_incluir" };
  } else if (msg === "3") {
    reply = formatMenu();
    newState = { step: "menu" };
  } else {
    reply = "Digite 1 para confirmar, 2 para corrigir, ou 3 para voltar ao menu.";
    newState = state;
  }
} else if (state.step === "confirmando_excluir") {
  if (msg === "1") {
    const p = state.pendente;
    const removido = config.servicos.splice(p.idx, 1)[0];
    newConfig = config;
    reply = `Serviço "${removido.nome}" removido.\n\n` + formatMenu();
    newState = { step: "menu" };
  } else if (msg === "2") {
    const lista = config.servicos.map(s => "- " + s.nome).join('\n');
    reply = "Envie novamente o nome exato do serviço que deseja excluir:\n" + lista;
    newState = { step: "aguardando_excluir" };
  } else if (msg === "3") {
    reply = formatMenu();
    newState = { step: "menu" };
  } else {
    reply = "Digite 1 para confirmar, 2 para corrigir, ou 3 para voltar ao menu.";
    newState = state;
  }
} else {
  reply = formatMenu();
  newState = { step: "menu" };
}

return {
  json: {
    reply,
    newStateJson: exit ? null : JSON.stringify(newState),
    exit,
    newConfigJson: newConfig ? JSON.stringify(newConfig) : null
  }
};

let config = null;
try { config = JSON.parse($json.configRaw || 'null'); } catch (e) { config = null; }
if (!config || !config.servicos) {
  config = { servicos: [], horario: { dias: "Segunda a sábado", abertura: "09:00", fechamento: "19:00" } };
}

const servicosTexto = config.servicos
  .map(s => `| ${s.nome} | R$ ${Number(s.valor).toFixed(2).replace('.', ',')} | ${s.duracao} min |`)
  .join('\n');

const horarioTexto = `${config.horario.dias}: ${config.horario.abertura} às ${config.horario.fechamento}.`;

return { json: { ...$json, message: $('Mensagem Final').item.json.message, servicosTexto, horarioTexto } };
